// Builds test/fixtures/animation-mvp1-correction-fixture.json: an OFFLINE FIXTURE, hand-built, NOT generated by a model. It shows the
// MVP1 v2 correction together (owner 2026-11-02, items 4, 5 and 7): tube wireframe, one disclosed arrow scale with a scale bar, a zero
// update hidden and shown as 0, the real boundary crossing for an off-plot step, off plot told apart from diverged, four readouts.
// Derived from the repaired draft of the saved job aj_086fd46 (fixtures/animation-aj_086fd46.json). It proves how the rules look and
// compute on this one scene; it does not prove that a model's future generation follows them.
//   node build-animation-mvp1-correction-fixture.mjs
import { readFileSync, writeFileSync } from 'node:fs';
import { hashAnimationPlan, validateAnimationPlan } from '../web/src/animation3d/contract.js';
import { ANIMATION_CAPABILITIES } from '../web/src/animation3d/capabilities.js';

const saved = JSON.parse(readFileSync(new URL('./test/fixtures/animation-aj_086fd46.json', import.meta.url), 'utf8'));
const K = 2, TUBE = 0.04, ARROW_T = 2;

// ---- the plan: the saved accepted plan with the owner's item 7 and the zero/off-plot rules applied (strings rewritten clean) ----
const plan = structuredClone(saved.plan);
plan.parameters[2].label = 'Show full-batch update arrow';
plan.description = 'OFFLINE FIXTURE, not generated by a model. A bowl drawn as a wireframe of tubes shows the error (loss) for every pair of two model settings, a slope w and an intercept b. A marker starts on the bowl and each step moves it downhill along a noisy update, leaving a path of up to 40 points. Change the learning rate and batch size to see steps crawl, zig-zag or leave the plot.';
plan.interactions[2] = 'Show or hide the grey full-batch update arrow. Compare it with the orange noisy update arrow: both include the learning rate and share one disclosed drawing scale.';
plan.assumptions[3] = 'The update is: new settings = old settings − learning rate × noisy gradient.';
plan.assumptions[4] = 'Orange arrow: the noisy update (minus learning rate times noisy gradient). Grey arrow: the full-batch update (minus learning rate times exact full-data gradient). One drawing scale, 2 units of length per 1.0 of update, with a scale bar; an update of exactly 0 has no arrow and shows as 0.';
plan.assumptions[5] = 'Readouts: step number (out of 40), passes through the data (steps × batch size ÷ 64), full-data loss, and distance from the lowest point.';
plan.assumptions[6] = 'A run stops after 40 steps, or earlier as off plot when a step leaves the plotted area (the true position stays in the readouts). It is called diverged only when the learning rate is above 1.0, the limit this loss allows. The current path keeps at most 40 points, and so does the saved grey path.';
const planCheck = validateAnimationPlan(plan, ANIMATION_CAPABILITIES);
if (!planCheck.ok) throw new Error(JSON.stringify(planCheck.issues));
const planHash = await hashAnimationPlan(plan);

// ---- the scene ----
const r4 = x => Number(x.toFixed(2));
const geometries = [], nodes = [];
// Each tube has its own full-size points: a node's scale would scale the tube's thickness too.
const ring = (id, y) => { const a = Math.sqrt(y / 0.1), c = Math.sqrt(y / 0.4); geometries.push({ id: `g${id}`, kind: 'curve', closed: true, radius: TUBE, points: Array.from({ length: 8 }, (_, i) => [r4(a * Math.cos(i * Math.PI / 4)), y, r4(c * Math.sin(i * Math.PI / 4))]) }); nodes.push({ id, geometry: `g${id}`, material: 'bowl' }); };
[['c2', 0.4], ['c3', 0.9], ['c4', 1.6]].forEach(([id, y]) => ring(id, y));
const line = (id, material, pts) => { geometries.push({ id: `g${id}`, kind: 'curve', radius: TUBE, points: pts }); nodes.push({ id, geometry: `g${id}`, material }); };
const upto = (from, to, n) => Array.from({ length: n + 1 }, (_, i) => from + (to - from) * i / n);
line('axisW', 'bowl', upto(-4, 4, 4).map(w => [w, r4(0.1 * w * w), 0]));
line('axisB', 'bowl', upto(-2, 2, 4).map(b => [0, r4(0.4 * b * b), b]));
// the plot (|w| <= 4, |b| <= 2) as a pale rectangle on the floor: its footprint, whose edge is where an off-plot step is marked. A flat plane: nothing
// above it is covered. (A closed tube round the plot on the surface was a saddle, corners at 3.2 against the bowl's 1.6, that read as a scribble over
// the bowl; a closed curve on the floor bulged past its corners; four straight tubes did not fit the review request's size limit.)
geometries.push({ id: 'gedge', kind: 'plane', width: 8, height: 4 });
nodes.push({ id: 'edge', geometry: 'gedge', material: 'edge', position: [0, -0.01, 0], quaternion: [-0.7071, 0, 0, 0.7071] });
geometries.push(
  { id: 'ballG', kind: 'sphere', radius: 0.18, widthSegments: 24, heightSegments: 16 }, { id: 'd', kind: 'sphere', radius: 0.07, widthSegments: 10, heightSegments: 8 },
  { id: 'puckG', kind: 'cylinder', radius: 0.3, height: 0.08, radialSegments: 32 }, { id: 'minG', kind: 'sphere', radius: 0.1, widthSegments: 16, heightSegments: 12 },
  { id: 'exitG', kind: 'sphere', radius: 0.16, widthSegments: 16, heightSegments: 12 }, { id: 'arr', kind: 'arrow', length: 1 },
  { id: 'barG', kind: 'box', size: [2, 0.06, 0.06] },
  { id: 'lStart', kind: 'label', text: 'Start (drag)', placement: 'left' }, { id: 'lMin', kind: 'label', text: 'Lowest point', placement: 'right' },
  { id: 'lW', kind: 'label', text: 'slope w', placement: 'right' }, { id: 'lB', kind: 'label', text: 'intercept b', placement: 'below' },
  { id: 'lStatus', kind: 'label', text: 'Ready', placement: 'center' }, { id: 'lExit', kind: 'label', text: 'Left the plot here', placement: 'above' },
  { id: 'lStepG', kind: 'label', text: 'noisy update', placement: 'right' }, { id: 'lTrueG', kind: 'label', text: 'full-batch update', placement: 'right' },
  { id: 'lBar', kind: 'label', text: 'Scale bar: an update of 1.0 is this long', placement: 'right' });
nodes.push(
  { id: 'lw', geometry: 'lW', parent: 'axisW', position: [4.05, 1.6, 0] }, { id: 'lb', geometry: 'lB', parent: 'axisB', position: [0, 1.6, 2.05] },
  { id: 'minM', geometry: 'minG', material: 'min', position: [0, 0.05, 0] }, { id: 'lmin', geometry: 'lMin', parent: 'minM', position: [0.12, 0, 0] },
  { id: 'start', geometry: 'puckG', material: 'puck', position: [-2.8, 1.61, 1.3], drag: { axis: 'x', min: -3.2, max: 3.2 } },
  { id: 'lstart', geometry: 'lStart', parent: 'start', position: [-0.32, 0, 0] },
  { id: 'ball', geometry: 'ballG', material: 'ball', position: [-2.8, 1.64, 1.3] },
  { id: 'stepArrow', geometry: 'arr', material: 'stepA' }, { id: 'trueArrow', geometry: 'arr', material: 'trueA' },
  { id: 'lblStep', geometry: 'lStepG' }, { id: 'lblTrue', geometry: 'lTrueG' },
  { id: 'exitM', geometry: 'exitG', material: 'exitMat', position: [0, 0, 0], visible: false },
  { id: 'lexit', geometry: 'lExit', parent: 'exitM', position: [0, 0.16, 0] },
  { id: 'status', geometry: 'lStatus', position: [0, 3.6, 0] },
  { id: 'bar', geometry: 'barG', material: 'barMat', position: [0, 0.03, 2.8] },
  { id: 'lbar', geometry: 'lBar', parent: 'bar', position: [1.1, 0, 0] });
for (let i = 0; i < 40; i++) nodes.push({ id: `p${i}`, geometry: 'd', material: 't' });
for (let i = 0; i < 40; i++) nodes.push({ id: `o${i}`, geometry: 'd', material: 'g' });

const source = `const A=0.5,C=2,H=0.4,W0=-2.8,B0=1.3,K=${K},T=${ARROW_T},S=1.2,WM=4,BM=2,LIM=2/C,Q=0.7071067811865476;
const Lf=(w,b)=>0.5*(A*w*w+C*b*b);
const Y=(w,b)=>H*Lf(w,b);
const cl=(v,m)=>Math.max(-m,Math.min(m,v));
function rnd(n){const x=Math.sin(n)*43758.5453;return x-Math.floor(x);}
function nz(seed,run,k){const u=Math.max(rnd(seed*1.37+run*91.3+k*7.77+0.5),1e-9),v=rnd(seed*2.71+run*53.1+k*3.91+1.3),r=Math.sqrt(-2*Math.log(u));return [r*Math.cos(6.2832*v),r*Math.sin(6.2832*v)];}
function stepV(s,inp,seed){const B=+inp.batchSize,f=Math.sqrt((64-B)/(63*B)),n=nz(seed,s.run,s.k),lr=inp.learningRate;return [-lr*(A*s.w+S*f*n[0]),-lr*(C*s.b+S*f*n[1])];}
function fresh(w0,run,old){return {w0,run,old,w:w0,b:B0,k:0,t:0,st:0,path:[],ex:null,dv:false};}
export function initialState(){return fresh(W0,0,[]);}
function cross(w,b,d){let t=1;for(const [p,q,m] of [[w,d[0],WM],[b,d[1],BM]])if(Math.abs(p+q)>m)t=Math.min(t,((q>0?m:-m)-p)/q);return t;}
function adv(s,inp,seed){if(s.st)return s;const d=stepV(s,inp,seed),w=s.w+d[0],b=s.b+d[1],k=s.k+1,path=s.path.concat([[w,b]]).slice(-40);
if(Math.abs(w)>WM||Math.abs(b)>BM){const t=cross(s.w,s.b,d);return {...s,w,b,k,path,st:2,ex:[s.w+t*d[0],s.b+t*d[1]],dv:inp.learningRate>LIM};}
return {...s,w,b,k,path,st:k>=40?1:0};}
export function reduce({state:s,event:e,inputs,seed}){
if(e.type==='step'){if(s.st)return s;const t=s.t+1;return t%8?{...s,t}:adv({...s,t},inputs,seed);}
if(e.type==='action'){if(e.action==='oneStep')return adv(s,inputs,seed);if(e.action==='keepPath')return fresh(s.w0,s.run+1,s.path);}
if(e.type==='parameter'&&e.parameter!=='showTrueGradient')return fresh(s.w0,s.run,s.old);
if((e.type==='drag_move'||e.type==='drag_end')&&e.node==='start')return fresh(cl(e.value,3.2),s.run,s.old);
return s;}
function pt(p){if(!p||Math.abs(p[0])>WM||Math.abs(p[1])>BM)return {visible:false};return {visible:true,position:[p[0],Y(p[0],p[1])+0.06,p[1]]};}
function arr(x,y,z,d,on){const m=Math.hypot(d[0],d[1]);if(!on||m===0)return {visible:false};return {visible:true,position:[x,y,z],scale:[T,K*m,T],quaternion:[d[1]/m*Q,0,-d[0]/m*Q,Q]};}
function num(m){return m===0?'0':String(+m.toPrecision(2));}
export function evaluate({inputs,seed,state:s}){const n={},lr=inputs.learningRate,B=+inputs.batchSize,run=s.st===0,off=s.st===2;
for(let i=0;i<40;i++){n['p'+i]=pt(s.path[i]);n['o'+i]=pt(s.old[i]);}
n.start={position:[s.w0,Y(s.w0,B0)+0.04,B0]};
n.ball=off?{visible:false}:{position:[s.w,Y(s.w,s.b)+0.18,s.b]};
if(run){const y=Y(s.w,s.b)+0.18,u=stepV(s,inputs,seed),f=[-lr*A*s.w,-lr*C*s.b],mu=Math.hypot(u[0],u[1]),mf=Math.hypot(f[0],f[1]),show=inputs.showTrueGradient;
n.stepArrow=arr(s.w,y+0.22,s.b,u,true);n.trueArrow=arr(s.w,y+0.4,s.b,f,show);
n.lblStep={visible:true,text:'noisy update '+num(mu),position:[s.w+K*u[0]+0.05,y+0.1,s.b+K*u[1]]};
n.lblTrue={visible:show,text:'full-batch update '+num(mf),position:[s.w+K*f[0]+0.05,y+0.52,s.b+K*f[1]]};}
else{n.stepArrow={visible:false};n.trueArrow={visible:false};n.lblStep={visible:false};n.lblTrue={visible:false};}
n.exitM=off?{visible:true,position:[s.ex[0],0.1,s.ex[1]]}:{visible:false};
n.status={text:off?(s.dv?'Diverged at step '+s.k+': off plot, learning rate above '+LIM.toFixed(1):'Off plot at step '+s.k+': stopped, not proven diverged'):s.st===1?'Done: 40 steps':s.k?'Running':'Ready'};
return {nodes:n,readouts:{loss:Lf(s.w,s.b),dist:Math.hypot(s.w,s.b),stepNo:s.k,passes:s.k*B/64}};}`;

const draft = {
  title: 'Offline fixture: Stochastic Gradient Descent on a Loss Bowl',
  description: 'OFFLINE FIXTURE, not generated by a model. A wireframe bowl of tubes shows loss over slope w and intercept b. An orange ball steps downhill; an orange arrow is the noisy update, a grey arrow the full-batch update, at one scale shown by the scale bar.',
  experience: plan.experience, behavior: plan.behavior, controlProfile: plan.controlProfile, stepped: true,
  scene: { materials: [{ id: 'bowl', color: '#3f6fa8' }, { id: 'edge', color: '#8f99a6', opacity: 0.25 }, { id: 'ball', color: '#e8692a' }, { id: 't', color: '#f07a30' }, { id: 'g', color: '#8a8a8a' }, { id: 'puck', color: '#3a9a5b' },
    { id: 'min', color: '#333344' }, { id: 'stepA', color: '#d9481c' }, { id: 'trueA', color: '#555555' }, { id: 'exitMat', color: '#c01818' }, { id: 'barMat', color: '#222222' }], geometries, nodes },
  parameters: structuredClone(plan.parameters),
  actions: [{ id: 'oneStep', label: 'Take one step' }, { id: 'keepPath', label: 'New run, keep old path' }],
  readouts: [{ id: 'loss', label: 'Full-data loss', decimals: 3 }, { id: 'dist', label: 'Distance from lowest point', decimals: 3 }, { id: 'stepNo', label: 'Step (of 40)', decimals: 0 }, { id: 'passes', label: 'Passes through the data', decimals: 3 }],
  seed: 7, camera: { position: [5.5, 6, 7.5], target: [0, 1, 0], fov: 42 },
  assumptions: [
    'Offline fixture, not generated by a model. Simplified simulation: an idealized loss bowl with simulated batch noise, not a model trained on real data.',
    'Loss L = 0.5(0.5 w² + 2 b²), lowest at w=b=0, steeper along b. New = old − learning rate × noisy gradient. With the full batch, b zig-zags above learning rate 0.5 and grows every step above 1.0.',
    'Noise per component = 1.2 × N(0,1) × sqrt((64−B)/(63B)): 1.2 at B=1, exactly 0 at B=64. A noisy step can raise the full-data loss; it falls only on average.',
    'Orange arrow: noisy update (minus learning rate × noisy gradient). Grey: full-batch update (minus learning rate × exact gradient). One scale, 2 units of length per 1.0 of update (the scale bar), no minimum or maximum length. An update of 0 has no arrow; its label reads 0.',
    'The pale rectangle on the floor is the plot (|w| ≤ 4, |b| ≤ 2); its edge is the plot edge. A step crossing it stops the run and is marked where it crosses; readouts keep true values. Diverged only if the learning rate is above 1.0, else Off plot.',
    'Readouts: loss, distance, step (of 40), passes through the data (steps × batch size ÷ 64). One update per 8 host steps. Changing a parameter restarts the run (same noise) and keeps the grey path.',
    'Dragging the start moves it along w only (b stays 1.3) and restarts the run. Reset replays the same noise; New run, keep old path draws new noise.'],
  program: { source },
};

const out = {
  offlineFixture: 'OFFLINE FIXTURE. Hand-built from the repaired draft of aj_086fd46 to show the MVP1 v2 correction together. NOT generated by a model, not reviewed by a model, and not evidence that any future generation follows these rules.',
  qualification: { readoutIds: { step: 'stepNo', passes: 'passes', loss: 'loss', dist: 'dist' }, note: 'The approved plan names the four readouts in prose only (assumptions[5]); it supplies no ids, so the ids are declared here and the checker never matches labels.' },
  resultId: 'ar_0ff11e000ff11e000ff11e000ff11e00', planHash, approvalAt: 1793684978812, plan, draft,
};
writeFileSync(new URL('./test/fixtures/animation-mvp1-correction-fixture.json', import.meta.url), JSON.stringify(out, null, 1) + '\n');
console.log('wrote fixture', planHash.slice(0, 12), `${source.length} source bytes`, `${nodes.length} nodes`);

// The same fixture as the real validateStage seals it, for the dev preview: the owner's launcher posts it to the dev-only seed-fixture route, which stores it as a
// saved result (animation-job.js ANIMATION_SEED_FIXTURE_PATH). Nothing here is bundled into the app or the Workers.
const { validateStage } = await import('./src/animation-author.js');
const PROMPT = 'Show me how stochastic gradient descent works. Let me change the learning rate and batch size to see what happens.';
const sealed = await validateStage({ prompt: PROMPT, evidence: [], context: null, plan, planHash, resultId: out.resultId, approval: { at: out.approvalAt }, draft, calls: [], features: ['curve_radius'] }, { env: {} });
if (!sealed.artifact) throw new Error(`the fixture does not validate: ${JSON.stringify(sealed.problems)}`);
writeFileSync(new URL('./test/fixtures/animation-mvp1-correction-artifact.json', import.meta.url), JSON.stringify(sealed.artifact) + String.fromCharCode(10));
console.log('wrote the sealed artifact', sealed.artifactHash.slice(0, 12));
